//! Scoped collaboration requests from an executing specialist.
use crate::{
    ids::{CommandId, TaskId, WorkspaceId},
    values::MessageText,
};
use serde::{Deserialize, Serialize};
/// A durable tool invocation. Its identity is retained across transport retries.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ToolRequest {
    /// Executing parent dispatch; authenticates scope alongside the node token.
    pub parent: CommandId,
    /// Unique idempotency identity generated by the local journal.
    pub id: CommandId,
    /// Bounded, typed operation; no arbitrary URL or executable.
    pub action: ToolAction,
}
/// The minimal collaboration surface exposed to providers.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum ToolAction {
    /// Inspect available peers and registered workspaces.
    Agents {},
    /// Start one scoped child task, using existing configured permissions.
    Delegate {
        /// Destination workspace chosen from discovery.
        workspace_id: WorkspaceId,
        /// Work to perform; does not grant additional permissions.
        message: MessageText,
        /// Evidence expected from the child.
        acceptance: MessageText,
    },
    /// Read a child of this conversation, including its latest outcome.
    Task {
        /// Child identity returned by delegation.
        task_id: TaskId,
    },
}
